    int32_t text_colour[16];           /* +0x06c 4 x 4 ints, row r at +0x6c + r * 0x10; column q is set by Widget_setQuad / _70 / _74 / _78; defaults rows 0..3 = (0,-1,-1,-1), (-1 x4), (2 x4), (2 x4) */
